using System;
using System.IO;
using System.IO.Compression;
using System.Reflection;
using System.Threading;
namespace PZ3D {
 static class SteamVersionWorkflowTests {
  static int checks;static Type api;static object workflow;
  static void Check(bool ok,string name){if(!ok)throw new Exception("FAIL "+name);checks++;}
  static object Call(string name,params object[] args){try{return api.GetMethod(name).Invoke(workflow,args);}catch(TargetInvocationException x){throw x.InnerException;}}
  static string S(object row,string key){return (string)row.GetType().GetField(key).GetValue(row);}
  static void Refuses(Action action,string name){bool rejected=false;try{action();}catch{rejected=true;}Check(rejected,name);}
  static void Put(string path,string text){Directory.CreateDirectory(Path.GetDirectoryName(path));File.WriteAllText(path,text);}
  static void Jar(string root,string game,int major){byte[] bytes=(byte[])typeof(GameVersionProbeTests).GetMethod("Compile",BindingFlags.NonPublic|BindingFlags.Static).Invoke(null,new object[]{root,"new GameVersion("+major+",21,\"\")"});string path=Path.Combine(game,"projectzomboid.jar");if(File.Exists(path))File.Delete(path);using(var archive=ZipFile.Open(path,ZipArchiveMode.Create))using(var stream=archive.CreateEntry("zombie/core/Core.class").Open())stream.Write(bytes,0,bytes.Length);}
  static void Manifest(string path,int flags,string branch,string done="0",string total="0"){Put(path,"\"AppState\"\n{\n\"appid\" \"108600\"\n\"installdir\" \"ProjectZomboid\"\n\"StateFlags\" \""+flags+"\"\n\"buildid\" \"12345\"\n\"BytesDownloaded\" \""+done+"\"\n\"BytesToDownload\" \""+total+"\"\n\"UserConfig\" { \"BetaKey\" \""+branch+"\" }\n}");}
  public static int Main(){try{Run();return 0;}catch(Exception x){Console.WriteLine(x);return 1;}}
  public static void Run(){api=typeof(Engine).Assembly.GetType("PZ3D.SteamVersionWorkflow");Check(api!=null,"official interactive installation workflow exists");string root=Path.Combine(LauncherTestPaths.Root,"steam-version-"+Guid.NewGuid().ToString("N"));try{
   string game=Path.Combine(root,"steamapps","common","ProjectZomboid"),manifest=Path.Combine(root,"steamapps","appmanifest_108600.acf"),data=Path.Combine(root,"data"),user=Path.Combine(root,"user"),target=Path.Combine(root,"versions","B41");Put(Path.Combine(game,"ProjectZomboid64.exe"),"fixture executable");Put(Path.Combine(game,"ProjectZomboid64.json"),"{\"vmArgs\":[]}");Jar(root,game,42);Manifest(manifest,4,"unstable");workflow=Activator.CreateInstance(api,new object[]{data,game,user});object job=Call("BeginInteractive",41,target,"B41",CancellationToken.None,null);
   Check(S(job,"Stage")=="awaiting-steam"&&S(job,"SteamUri")=="steam://nav/games/details/108600","returns honest Steam interaction step with fixed App108600 link");string preservedId=S(job,"PreservedVersionId");var lib=new VersionLibrary(data,game,user);Check(lib.List().Count==2&&lib.List()[1].Id==preservedId&&lib.List()[1].GamePath!=game,"current official version is fully preserved before Steam branch choice");
   Check(GameVersionProbe.Read(game).Major==42&&File.ReadAllText(manifest).Contains("unstable"),"begin does not mutate Steam branch or canonical installation");Refuses(()=>Call("Complete",CancellationToken.None,null),"wrong actual version cannot become installed");Manifest(manifest,1026,"legacy41","50","100");Check(S(Call("State"),"Stage")=="downloading","manifest download state remains separate from installed rows");Jar(root,game,41);Refuses(()=>Call("Complete",CancellationToken.None,null),"matching game files during incomplete Steam install are not launchable");Manifest(manifest,4,"legacy41","100","100");Check(S(Call("State"),"Stage")=="ready-to-preserve","Steam installed manifest plus actual requested major enables preservation");
   object installed=Call("Complete",CancellationToken.None,null);Check(S(installed,"GamePath")==target&&GameVersionProbe.Read(target).Major==41&&lib.List().Count==3,"verified requested branch becomes a full independent version");Check(GameVersionProbe.Read(lib.List()[1].GamePath).Major==42,"previous version remains intact after canonical Steam branch changes");Check(S(Call("State"),"Stage")=="saved"&&S(Call("State"),"InstalledVersionId")==S(installed,"Id"),"download workflow records final saved identity only after copy succeeds");Refuses(()=>Call("Complete",CancellationToken.None,null),"completed workflow cannot create duplicate installations");
   Manifest(manifest,1026,"legacy41");Refuses(()=>Call("BeginInteractive",42,Path.Combine(root,"other"),"B42",CancellationToken.None,null),"cannot preserve Steam canonical folder while it is downloading");
   Manifest(manifest,4,"legacy41");Call("BeginInteractive",42,Path.Combine(root,"cancelled-target"),"B42",CancellationToken.None,null);Call("Cancel");Check(S(Call("State"),"Stage")=="cancelled"&&!Directory.Exists(Path.Combine(root,"cancelled-target")),"cancel preserves prior version and never fakes installed content");
   string raced=Path.Combine(root,"raced-target");Call("BeginInteractive",42,raced,"B42",CancellationToken.None,null);int records=lib.List().Count;Jar(root,game,42);Manifest(manifest,4,"unstable");bool changed=false;Action<VersionCopyProgress> update=p=>{if(!changed){changed=true;Manifest(manifest,1026,"unstable","1","100");}};Refuses(()=>Call("Complete",CancellationToken.None,update),"Steam state changing during preservation aborts before version publication");Check(!Directory.Exists(raced)&&lib.List().Count==records,"failed completion leaves no launchable record or destination");Call("Cancel");
   Manifest(manifest,4,"unstable");string good=File.ReadAllText(manifest);File.WriteAllText(manifest,good.Replace("\"appid\" \"108600\"","\"appid\" \"999\""));Refuses(()=>Call("BeginInteractive",41,Path.Combine(root,"wrong-app"),"B41",CancellationToken.None,null),"foreign app manifest cannot authorize a Project Zomboid installation step");File.WriteAllText(manifest,good.Replace("\"appid\" \"108600\"","\"appid\" \"108600\"\n\"appid\" \"108600\""));Refuses(()=>Call("BeginInteractive",41,Path.Combine(root,"duplicate-app"),"B41",CancellationToken.None,null),"ambiguous duplicate manifest fields rejected");
   Console.WriteLine("SteamVersionWorkflow PASS: "+checks+" assertions");
  }finally{string full=Path.GetFullPath(root),allowed=Path.GetFullPath(LauncherTestPaths.Root)+Path.DirectorySeparatorChar;if(!full.StartsWith(allowed,StringComparison.OrdinalIgnoreCase)||!Path.GetFileName(full).StartsWith("steam-version-"))throw new IOException("Unsafe fixture cleanup");if(Directory.Exists(full))Directory.Delete(full,true);}}
 }
}
